/**
 * Numbered page controls for paged lists (`design/components/pagination.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/pagination.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  Icon,
  PAGINATION_ELLIPSIS,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  itemOf,
  paginationWindow,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/pagination.module.css'
import Button from '../controls/Button'
import Inline from '../layout/Inline'

export type SiblingCount = NonNullable<PaginationProps['siblingCount']>

export interface PaginationMessages {
  previous: string
  next: string
  page: (page: number) => string
}

export interface PaginationProps {
  /**
   * The app holds the pager while it does something else to the list: every control is disabled,
   * the current page too, and no page is asked for.
   */
  disabled?: boolean
  /**
   * A page's address, such as `?page=3`. Given, each control that goes to another page is a link
   * to that page's address, so a crawler, a new tab and a reader whose script has not loaded can
   * follow it. A click the browser would follow in this tab calls `onPageChange` in place of the
   * navigation; a click with a modifier key opens the address. The current page, a control with
   * nowhere to go and a held pager's controls stay buttons.
   */
  getPageHref?: (page: number) => string
  label?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: PaginationMessages
  onPageChange: (page: number) => void
  /**
   * 1-based and controlled, because the current page belongs to the list.
   */
  page: number
  pageCount: number
  siblingCount?: 1 | 2
}

/** Numbered page controls for paged lists. */
export default function Pagination(given: PaginationProps): JSX.Element {
  const props = mergeProps(
    {
      siblingCount: 1,
      disabled: false,
      label: 'Pagination',
      messages: (() => ({
        previous: 'Previous page',
        next: 'Next page',
        page: (page) => `Page ${page}`,
      }))(),
    } as Defaults<PaginationProps, 'siblingCount' | 'disabled' | 'label' | 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const focused = createCell(null as HTMLElement | null)
    const focusedControl = createCell(null as string | number | null)
    const taken = createCell(null as string | number | null)
    const root = elementRef<HTMLElement>()
    const entries = createDerived(() =>
      paginationWindow(props.page, props.pageCount, props.siblingCount),
    )
    const controls = createDerived(() => [
      'previous',
      ...entries.value.filter((shown) => shown !== PAGINATION_ELLIPSIS),
      'next',
    ])
    const focusIn = createDerived(() => (event: FocusEvent) => {
      const target = event.target as HTMLElement
      const pager = root.value as HTMLElement | null
      const names: readonly (string | number)[] = controls.value
      const at =
        pager === null ? -1 : [...pager.querySelectorAll('button, a[href]')].indexOf(target)
      focused.value = target
      focusedControl.value = at < 0 ? null : (names[at] ?? null)
    })
    const focusOut = createDerived(() => (event: FocusEvent) => {
      const target = event.target as HTMLElement
      if (target.matches(':disabled')) return
      queueMicrotask(() => {
        if (focused.value === target && target.isConnected) focused.value = null
      })
    })
    const keepPlace = createDerived(() => () => {
      const pager = root.value as HTMLElement | null
      if (pager === null) return
      const names: readonly (string | number)[] = controls.value
      const drawn = () => [...pager.querySelectorAll<HTMLElement>('button, a[href]')]
      const onPage = () =>
        document.activeElement === null || document.activeElement === document.body
      const left = focused.value as HTMLElement | null
      if (left !== null && !left.isConnected) {
        focused.value = null
        const name = focusedControl.value
        const now = name === null ? undefined : drawn()[names.indexOf(name)]
        if (now !== undefined && onPage()) {
          if (now.matches(':disabled')) focused.value = now
          else now.focus()
        }
      }
      if (!props.disabled) {
        const control = taken.value
        taken.value = null
        if (control === null || document.activeElement !== pager) return
        const element = drawn()[names.indexOf(control)]
        if (element !== undefined && !element.matches(':disabled')) element.focus()
        return
      }
      const from = focused.value as HTMLElement | null
      if (from === null || !from.isConnected || !from.matches(':disabled')) return
      const active = document.activeElement
      if (active !== from && active !== null && active !== document.body) return
      taken.value = names[drawn().indexOf(from)] ?? null
      pager.focus()
    })
    const linked = createDerived(() => !props.disabled && props.getPageHref !== undefined)
    const navigatesHere = createDerived(
      () =>
        (event: MouseEvent): boolean =>
          !event.defaultPrevented &&
          event.button === 0 &&
          !event.metaKey &&
          !event.ctrlKey &&
          !event.shiftKey &&
          !event.altKey,
    )
    const follow = createDerived(() => (event: MouseEvent, to: number): void => {
      if (!navigatesHere.value(event)) return
      event.preventDefault()
      props.onPageChange?.(to)
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const run = () => {
        keepPlace.value()
      }
      const mutation =
        typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
      for (const element of [root.value])
        if (element)
          mutation?.observe(element, {
            childList: true,
            characterData: true,
            subtree: true,
            attributeFilter: ['disabled'],
          })
      release1 = () => {
        mutation?.disconnect()
      }
      run()
    }
    watchEffect(
      createMemo(() => entries.value.length > 0),
      effect1,
      true,
    )
    onCleanup(() => release1?.())
    const effect2 = () => {
      keepPlace.value()
    }
    watchEffect(
      createMemo(() => props.disabled),
      effect2,
      false,
    )
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = agentMember({
        member: 'Pagination',
        element: () => root.value,
        state: () => ({
          page: props.page,
          'page-count': props.pageCount,
          disabled: props.disabled,
        }),
        actions: {
          set: {
            argument: 'number',
            run: (value) =>
              (() => {
                if (!Number.isInteger(value) || value < 1 || value > props.pageCount) {
                  throw new Error(
                    `There is no page ${value}; the pages run from 1 to ${props.pageCount}.`,
                  )
                }
                if (value !== props.page) props.onPageChange?.(value)
              })(),
          },
        },
        withholds: () => root.value,
      })
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    return (
      <>
        {entries.value.length > 0 ? (
          <nav
            class={styles.pagination}
            aria-label={props.label}
            data-disabled={props.disabled ? '' : undefined}
            tabindex="-1"
            data-member="pagination"
            onfocusin={($event: FocusEvent) => focusIn.value($event)}
            onfocusout={($event: FocusEvent) => focusOut.value($event)}
            ref={root.attach}
          >
            <Inline gap={1} align="center" wrap={true}>
              {linked.value && props.page > 1 && props.page - 1 <= props.pageCount ? (
                <a
                  class={styles.link}
                  href={props.getPageHref?.(props.page - 1)}
                  aria-label={props.messages.previous}
                  data-variant="ghost"
                  data-size="sm"
                  data-tone="neutral"
                  data-icon-only={''}
                  onclick={($event: MouseEvent) => follow.value($event, props.page - 1)}
                >
                  {/* glyph */}
                  <span class={styles.linkGlyph}>
                    <Icon name="previous" size="sm" />
                  </span>
                </a>
              ) : (
                <Button
                  variant="ghost"
                  tone="neutral"
                  size="sm"
                  iconOnly={true}
                  icon="previous"
                  label={props.messages.previous}
                  disabled={props.disabled || props.page <= 1}
                  onClick={() => props.onPageChange?.(props.page - 1)}
                />
              )}
              <Each
                of={entries.value}
                by={(entry, at) => (entry === PAGINATION_ELLIPSIS ? `gap-${at}` : entry)}
                renew
              >
                {(entry) => (
                  <>
                    {entry === PAGINATION_ELLIPSIS ? (
                      <span class={styles.ellipsis} aria-hidden="true">
                        …
                      </span>
                    ) : linked.value && entry !== props.page ? (
                      <a
                        class={styles.link}
                        href={props.getPageHref?.(itemOf(entry))}
                        aria-label={props.messages.page(itemOf(entry))}
                        data-variant="ghost"
                        data-size="sm"
                        data-tone="neutral"
                        onclick={($event: MouseEvent) => follow.value($event, itemOf(entry))}
                      >
                        {/* label */}
                        <span class={styles.linkLabel}>{String(entry)}</span>
                      </a>
                    ) : (
                      <Button
                        variant={entry === props.page ? 'soft' : 'ghost'}
                        tone={entry === props.page ? 'accent' : 'neutral'}
                        size="sm"
                        current={entry === props.page}
                        label={String(entry)}
                        aria-label={props.messages.page(itemOf(entry))}
                        disabled={props.disabled}
                        onClick={() => entry !== props.page && props.onPageChange?.(itemOf(entry))}
                      />
                    )}
                  </>
                )}
              </Each>
              {linked.value && props.page < props.pageCount && props.page + 1 >= 1 ? (
                <a
                  class={styles.link}
                  href={props.getPageHref?.(props.page + 1)}
                  aria-label={props.messages.next}
                  data-variant="ghost"
                  data-size="sm"
                  data-tone="neutral"
                  data-icon-only={''}
                  onclick={($event: MouseEvent) => follow.value($event, props.page + 1)}
                >
                  {/* glyph */}
                  <span class={styles.linkGlyph}>
                    <Icon name="next" size="sm" />
                  </span>
                </a>
              ) : (
                <Button
                  variant="ghost"
                  tone="neutral"
                  size="sm"
                  iconOnly={true}
                  icon="next"
                  label={props.messages.next}
                  disabled={props.disabled || props.page >= props.pageCount}
                  onClick={() => props.onPageChange?.(props.page + 1)}
                />
              )}
            </Inline>
          </nav>
        ) : null}
      </>
    )
  })
}
